={{ {
  "from": "ChambaPe <hola@chambape.pe>",
  "to": $json.email,
  "subject": "Clientes buscan " + ($json.categoria || "técnicos") + " en " + ($json.distrito || "tu zona") + " — únete gratis",
  "html": "<h2>Hola" + ($json.nombre ? (" " + $json.nombre) : "") + ",</h2><p>Te escribimos de <strong>ChambaPe</strong>, una plataforma donde clientes de " + ($json.distrito || "Lima") + " publican trabajos que necesitan y técnicos como tú reciben las solicitudes para cotizar.</p><p>Registrarte es gratis y tú decides qué trabajos tomar y a qué precio.</p><p><a href='https://chambape.pe/registrarse' style='background:#f97316;color:white;padding:12px 24px;border-radius:8px;text-decoration:none;display:inline-block'>Registrarme gratis</a></p><p style='color:#9ca3af;font-size:12px;margin-top:24px'>Si no quieres recibir más correos de este tipo, <a href='https://chambape.pe/baja?lead=" + $json.id + "'>haz clic aquí para darte de baja</a>.</p>"
} }}
